head.b:skin:
/*
-----------------------------------------------
TBB Lite
Version: 1.0.1
Author:  The Bukit Besi (https://www.thebukitbesi.com/)
----------------------------------------------- */

/* Variable definitions
<Group description="Brand" selector="body">
  <Variable name="brand.color" description="Brand colour (links, buttons)" type="color" default="#e5002b" value="#e5002b"/>
  <Variable name="brand.ink" description="Text on brand colour" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="link.color" description="Links (light mode, 4.5:1 on cards)" type="color" default="#dd002a" value="#dd002a"/>
</Group>
<Group description="Light colours" selector="body">
  <Variable name="page.bg" description="Page background" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="surface.bg" description="Card and header background" type="color" default="#f6f6f7" value="#f6f6f7"/>
  <Variable name="text.color" description="Text" type="color" default="#18181b" value="#18181b"/>
  <Variable name="muted.color" description="Dates and captions" type="color" default="#5b5b66" value="#5b5b66"/>
  <Variable name="line.color" description="Borders" type="color" default="#e4e4e7" value="#e4e4e7"/>
</Group>
<Group description="Dark mode colours" selector="body">
  <Variable name="dark.bg" description="Dark page background" type="color" default="#0f0f12" value="#0f0f12"/>
  <Variable name="dark.surface" description="Dark card background" type="color" default="#1b1b20" value="#1b1b20"/>
  <Variable name="dark.text" description="Dark mode text" type="color" default="#ececf1" value="#ececf1"/>
  <Variable name="dark.muted" description="Dark mode muted text" type="color" default="#a1a1aa" value="#a1a1aa"/>
  <Variable name="dark.line" description="Dark mode borders" type="color" default="#2e2e35" value="#2e2e35"/>
  <Variable name="dark.link" description="Links (dark mode, 4.5:1 on cards)" type="color" default="#ff2d54" value="#ff2d54"/>
</Group>
<Group description="Fonts" selector="body">
  <Variable name="body.font" description="Body font" type="font" default="normal 400 17px system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif" value="normal 400 17px system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif"/>
  <Variable name="heading.font" description="Heading font" type="font" default="normal 700 16px system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif" value="normal 700 16px system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif"/>
</Group>
<Group description="Layout" selector="body">
  <Variable name="content.width" description="Maximum page width" type="length" default="1140px" min="960px" max="1400px" value="1140px"/>
  <Variable name="sidebar.width" description="Sidebar width (desktop)" type="length" default="320px" min="260px" max="380px" value="320px"/>
</Group>
*/

:root{
  --tbb-brand:$(brand.color);--tbb-brand-ink:$(brand.ink);--tbb-link:$(link.color);
  --tbb-bg:$(page.bg);--tbb-surface:$(surface.bg);--tbb-text:$(text.color);--tbb-muted:$(muted.color);--tbb-line:$(line.color);
  --tbb-max:$(content.width);--tbb-side:$(sidebar.width);--tbb-radius:12px;--tbb-gap:clamp(16px,3vw,32px)
}
@media (prefers-color-scheme:dark){
  :root{--tbb-bg:$(dark.bg);--tbb-surface:$(dark.surface);--tbb-text:$(dark.text);--tbb-muted:$(dark.muted);--tbb-line:$(dark.line);--tbb-link:$(dark.link)}
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
body{margin:0;font:$(body.font);line-height:1.7;color:var(--tbb-text);background:var(--tbb-bg);overflow-wrap:break-word}
h1,h2,h3,h4{font:$(heading.font);line-height:1.25;margin:1.6em 0 .6em}
h1{font-size:clamp(1.75rem,4vw,2.4rem);margin-top:0}
h2{font-size:clamp(1.35rem,3vw,1.7rem)}
h3{font-size:1.2rem}
a{color:var(--tbb-link);text-underline-offset:.18em}
a:hover{text-decoration-thickness:2px}
img,video,iframe{max-width:100%}
img{height:auto}
:focus-visible{outline:3px solid var(--tbb-brand);outline-offset:2px}
.tbb-sr{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.tbb-skip{position:absolute;left:8px;top:-60px;z-index:10;padding:10px 14px;border-radius:8px;background:var(--tbb-brand);color:var(--tbb-brand-ink)}
.tbb-skip:focus{top:8px}
.tbb-wrap{width:100%;max-width:var(--tbb-max);margin:0 auto;padding:0 16px}

/* Header and menu */
.tbb-header{background:var(--tbb-surface);border-bottom:1px solid var(--tbb-line)}
.tbb-header__bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px 16px;min-height:64px;padding-block:8px}
.tbb-header .widget{margin:0}
.tbb-brand{display:flex;align-items:center;gap:10px;color:var(--tbb-text);text-decoration:none}
.tbb-brand__title{margin:0;font:$(heading.font);font-size:1.3rem;line-height:1.2}
.tbb-brand__logo{display:block;max-height:48px;width:auto}
.tbb-brand__tagline{margin:2px 0 0;font-size:.85rem;color:var(--tbb-muted)}
.tbb-menu-btn{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;margin-left:auto;padding:0;color:var(--tbb-text);background:none;border:0;border-radius:8px;cursor:pointer}
.tbb-menu-btn[hidden]{display:none}
.tbb-menu-btn svg{width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:2}
.tbb-menu ul{list-style:none;margin:0;padding:8px 0}
.tbb-menu a{display:flex;align-items:center;min-height:44px;padding:0 12px;border-radius:8px;color:var(--tbb-text);text-decoration:none;font-weight:600}
.tbb-menu a:hover{background:var(--tbb-bg)}
.tbb-search{display:flex;flex:1 1 100%;min-width:0;gap:8px;margin:0}
.tbb-search input{flex:1;min-width:0;min-height:44px;padding:0 14px;font:inherit;font-size:1rem;color:var(--tbb-text);background:var(--tbb-bg);border:1px solid var(--tbb-line);border-radius:999px}
.tbb-btn,.tbb-search button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 18px;font:inherit;font-size:.95rem;font-weight:600;color:var(--tbb-brand-ink);background:var(--tbb-brand);border:0;border-radius:999px;cursor:pointer;text-decoration:none}

/* Layout */
.tbb-main{display:grid;gap:var(--tbb-gap);padding-block:var(--tbb-gap)}
.tbb-content{min-width:0}
.tbb-slot .widget{margin:0 0 var(--tbb-gap)}
.tbb-slot .widget:has(ins.adsbygoogle){min-height:100px}

/* Post list */
.tbb-heading{margin:0 0 var(--tbb-gap);font-size:1.4rem}
.tbb-grid{display:grid;gap:var(--tbb-gap);grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr))}
.tbb-card{display:flex;flex-direction:column;background:var(--tbb-surface);border:1px solid var(--tbb-line);border-radius:var(--tbb-radius);overflow:hidden}
.tbb-card__thumb{display:block;aspect-ratio:16/9;background:var(--tbb-line)}
.tbb-card__thumb img{display:block;width:100%;height:100%;object-fit:cover}
.tbb-card__body{display:flex;flex-direction:column;gap:8px;padding:16px}
.tbb-card__title{margin:0;font-size:1.15rem}
.tbb-card__title a{color:var(--tbb-text);text-decoration:none}
.tbb-card__title a:hover{color:var(--tbb-link)}
.tbb-card__snippet{margin:0;color:var(--tbb-muted);font-size:.95rem;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.tbb-meta{display:flex;flex-wrap:wrap;gap:4px 12px;margin:0;font-size:.875rem;color:var(--tbb-muted)}
.tbb-meta a{color:inherit}
.tbb-pager{display:flex;justify-content:space-between;gap:12px;margin-top:var(--tbb-gap)}
.tbb-pager__next{margin-left:auto}
.tbb-empty{padding:24px;background:var(--tbb-surface);border-radius:var(--tbb-radius)}

/* Single post */
.tbb-crumbs ol{display:flex;flex-wrap:wrap;gap:4px;list-style:none;margin:0 0 12px;padding:0;font-size:.875rem;color:var(--tbb-muted)}
.tbb-crumbs li+li::before{content:"/";margin-right:4px}
.tbb-crumbs a{color:inherit}
.tbb-post__header{margin-bottom:24px}
.tbb-post__body{font-size:1.06rem}
.tbb-post__body img{border-radius:8px}
.tbb-post__body a img{display:inline-block}
.tbb-post__body blockquote{margin:1.5em 0;padding:4px 0 4px 18px;border-left:4px solid var(--tbb-brand);color:var(--tbb-muted)}
.tbb-post__body pre{overflow:auto;padding:16px;background:var(--tbb-surface);border:1px solid var(--tbb-line);border-radius:8px;font-size:.9rem;line-height:1.5}
.tbb-post__body code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.92em}
.tbb-post__body table{display:block;overflow-x:auto;border-collapse:collapse;max-width:100%}
.tbb-post__body th,.tbb-post__body td{padding:8px 12px;border:1px solid var(--tbb-line);text-align:left}
.tbb-post__body iframe{display:block;aspect-ratio:16/9;width:100%;height:auto;border:0}
.tbb-post__body .tr-caption{font-size:.85rem;color:var(--tbb-muted)}
.tbb-tags{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:32px 0 0;padding:0}
.tbb-tags a,.tbb-labels a{display:inline-flex;align-items:center;min-height:36px;padding:0 14px;border:1px solid var(--tbb-line);border-radius:999px;color:var(--tbb-text);text-decoration:none;font-size:.9rem}
.tbb-tags a:hover,.tbb-labels a:hover{border-color:var(--tbb-brand);color:var(--tbb-link)}
.tbb-author{display:flex;gap:16px;align-items:flex-start;margin-top:32px;padding:20px;background:var(--tbb-surface);border-radius:var(--tbb-radius)}
.tbb-author img{border-radius:50%;flex:none}
.tbb-author strong a{display:inline-flex;align-items:center;min-height:24px}
.tbb-author p{margin:4px 0 0;font-size:.95rem;color:var(--tbb-muted)}
.tbb-comments{margin-top:40px;padding-top:24px;border-top:1px solid var(--tbb-line)}
.tbb-comments h2{margin-top:0}
.tbb-comments .comment-thread ol{list-style:none;margin:0;padding:0}
.tbb-comments .comment-thread li{margin:0 0 16px}
.tbb-comments .comment-replies{margin-left:20px;padding-left:16px;border-left:2px solid var(--tbb-line)}
.tbb-comments .avatar-image-container{float:left;margin-right:12px}
.tbb-comments .avatar-image-container img{width:36px;height:36px;border-radius:50%}
.tbb-comments .comment-block{overflow:hidden}
.tbb-comments .user{font-weight:700}
.tbb-comments .datetime,.tbb-comments .comment-actions{font-size:.85rem;color:var(--tbb-muted)}
.tbb-comments .comment-actions a{margin-right:12px}
.tbb-comments .thread-toggle,.tbb-comments .continue,.tbb-comments .loadmore{display:none}
.tbb-comments #comment-editor{display:block;width:100%;min-height:275px;border:0}

/* Sidebar and footer widgets */
.tbb-side .widget,.tbb-footer .widget{margin:0 0 var(--tbb-gap)}
.tbb-side .widget{padding:20px;background:var(--tbb-surface);border:1px solid var(--tbb-line);border-radius:var(--tbb-radius)}
.tbb-side h2,.tbb-side h3,.tbb-footer h2,.tbb-footer h3{margin:0 0 12px;font-size:1.05rem}
.tbb-side ul,.tbb-footer ul{list-style:none;margin:0;padding:0}
.tbb-labels{display:flex;flex-wrap:wrap;gap:8px}
.tbb-popular li{display:grid;grid-template-columns:72px 1fr;gap:12px;align-items:center;padding:8px 0}
.tbb-popular li+li{border-top:1px solid var(--tbb-line)}
.tbb-popular img{display:block;width:72px;height:72px;object-fit:cover;border-radius:8px}
.tbb-popular a{display:block;min-height:24px;color:var(--tbb-text);text-decoration:none;font-weight:600;line-height:1.35}
.tbb-popular a:hover{color:var(--tbb-link)}
.tbb-popular li:not(:has(img)){grid-template-columns:1fr}
.tbb-footer{margin-top:var(--tbb-gap);padding-block:var(--tbb-gap) 16px;background:var(--tbb-surface);border-top:1px solid var(--tbb-line);font-size:.95rem}
.tbb-footer__cols{display:grid;gap:var(--tbb-gap);grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr))}
.tbb-footer li a{display:inline-flex;align-items:center;min-height:36px;color:var(--tbb-text)}
.tbb-footer__bar{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;margin-top:16px;padding-top:16px;border-top:1px solid var(--tbb-line);color:var(--tbb-muted);font-size:.85rem}
.tbb-footer__bar a{color:inherit}

@media (min-width:768px){
  .tbb-menu-btn,.tbb-menu-btn[hidden]{display:none}
  .tbb-menu{margin-left:auto}
  .tbb-menu ul{display:flex;flex-wrap:wrap;gap:4px;padding:0}
  .tbb-search{flex:0 1 280px}
}
@media (max-width:767.98px){
  .tbb-menu{flex:1 1 100%;order:3}
  .tbb-js .tbb-menu:not(.is-open){display:none}
}
@media (min-width:1000px){
  .tbb-main{grid-template-columns:minmax(0,1fr) var(--tbb-side)}
  .tbb-main--wide{grid-template-columns:minmax(0,1fr)}
  .tbb-side{position:sticky;top:16px;align-self:start}
}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
@media print{.tbb-header,.tbb-side,.tbb-footer,.tbb-comments,.tbb-slot,.tbb-pager,.tbb-skip{display:none!important}body{background:#fff;color:#000}}

head.b:template-skin:
body#layout .tbb-wrap{max-width:900px}
body#layout .tbb-main{display:flex;gap:16px}
body#layout .tbb-content{flex:1}
body#layout .tbb-side{width:280px}
body#layout .tbb-footer__cols{display:flex;gap:16px}
body#layout .tbb-footer__cols > div{flex:1}
